-- Conteudo classificado para revisao. Nenhum registro pode ser aprovado nesta tabela.
-- status e translation_status ficam travados. Aprovar exige migracao posterior.
create table if not exists review_item (
  id text primary key,
  classe text not null,
  familia text not null,
  origem text not null,
  locale text not null,
  source_locale text not null default 'pt-BR',
  source_text text not null,
  texto text not null,
  revisao_clinica text not null check (revisao_clinica in ('aplicavel', 'nao_aplicavel')),
  fila text not null check (fila in ('revisao', 'pendencia')),
  status text not null default 'REVIEW_REQUIRED' check (status = 'REVIEW_REQUIRED'),
  translation_status text not null default 'DRAFT' check (translation_status = 'DRAFT'),
  aprovado boolean not null default false check (aprovado = false)
);
create index if not exists review_item_classe_idx on review_item (classe);
create index if not exists review_item_fila_idx on review_item (fila);
on conflict (id) do nothing;
